file.content:
mount_ok = drive_root is not None and drive_root.is_dir()
if drive_api_error:
    add("drive_api_unavailable", "", f"{drive_api_error}; used the Drive app's copy, which can be stale")
if not mount_ok and drive_api is None:
    add("drive_unreachable", "", "Drive checks skipped")
else:
    known_drive = {r.get("drive_folder") for r in rows if r.get("drive_folder")}
    for stage in STAGE_DIRS:
        if drive_api is not None:
            names = sorted(drive_api.get(stage, ()))
        else:
            base = drive_root / "01_PROJECTS" / stage
            names = sorted(p.name for p in base.iterdir() if p.is_dir()) if base.is_dir() else []
        for name in names:
            if f"01_PROJECTS/{stage}/{name}" not in known_drive:
                add("unregistered_drive", f"{stage}/{name}", _family_hint(name, rows))
    unchecked = []
    for r in rows:
        folder = r.get("drive_folder")
        if not folder or r.get("status") in RETIRED:
            continue
        parts = folder.split("/")
        if drive_api is not None and len(parts) == 3 and parts[0] == "01_PROJECTS" and parts[1] in STAGE_DIRS:
            if parts[2] not in drive_api.get(parts[1], ()):
                now = [s for s in STAGE_DIRS if parts[2] in drive_api.get(s, ())]
                add("missing_drive", r["name"], folder + (f"; Drive has it in {now[0]}" if now else ""))
        elif not mount_ok:
            unchecked.append(r["name"])
        elif not (drive_root / folder).exists():
            add("missing_drive", r["name"], folder)
    if unchecked:   # API covers stage folders only; other paths need the mount
        add("drive_unreachable", "", f"{len(unchecked)} row(s) outside 01_PROJECTS/<stage> not checked")

return {"status": "DRIFT" if problems else "OK", "problems": problems,
        "rows": len(rows), "drive_root": str(drive_root) if drive_root else None}

