# ---- projects ----------------------------------------------------------------

def project_index(registry: dict) -> list[tuple[str, str, str]]:
    """(root, prefix, project) sorted longest prefix first, so the most specific row wins."""
    idx = []
    for p in registry.get("projects", []):
        if p.get("dev_folder"):
            idx.append(("DEV", p["dev_folder"].replace("\\", "/").rstrip("/") + "/", p["name"]))
        if p.get("drive_folder"):
            idx.append(("DRIVE", p["drive_folder"].replace("\\", "/").rstrip("/") + "/", p["name"]))
    return sorted(idx, key=lambda t: -len(t[1]))


def project_for(e: dict, idx: list[tuple[str, str, str]]) -> str:
    for root, prefix, name in idx:
        if e["root"] == root and e["path"].startswith(prefix):
            return name
    head = e["path"].split("/", 1)[0]
    return {"DEV": f"(DEV) {head}", "DRIVE": f"(Drive) {head}", "VAULT": "(vault)"}.get(e["root"], head)


def keep(e: dict) -> bool:
    return not SENSITIVE.search("/" + e["path"])


# ---- ledger ------------------------------------------------------------------

def merge(old: list[dict], new: list[dict], now: _dt.datetime) -> list[dict]:
    """Latest entry per (root, path); entries older than KEEP_DAYS dropped; newest first."""
    cutoff = (now - _dt.timedelta(days=KEEP_DAYS)).isoformat()
    best: dict[tuple[str, str], dict] = {}
    for e in [*old, *new]:
        if e["when"] < cutoff:
            continue
        key = (e["root"], e["path"])
        if key not in best or e["when"] >= best[key]["when"]:
            if key in best and best[key]["how"].startswith("new") and not e["how"].startswith("new"):
                e = {**e, "how": "new"}  # a file first seen as new stays new
            best[key] = e
    return sorted(best.values(), key=lambda e: e["when"], reverse=True)


def ledger_path() -> Path:
    return LEDGER_DIR / f"{platform.node()}.jsonl"


