def _folder(p: dict) -> str:
    return p["dev_folder"].replace("\\", "/").strip("/")


def project_index(registry: dict, dev_root: Path | None = DEV) -> list[tuple[str, str, str]]:
    """(root, prefix, project) sorted longest prefix first, so the most specific row wins.

    A repo moved into an Area folder (plan Task 4, 2026-11-02: BAIR_Steering_Committee -> Program/...) also
    owns its old bare prefix, so ledger rows written before the move still count. Like merge_curation.py:
    direct <Area>/<Repo> only, and only when the owner is clear: one Area row with that repo name, no
    project/inbox/idea row claims the bare folder, and no `<dev_root>/<Repo>` exists today (an unregistered
    top-level repo of that name writes new X/ rows that are not this project's)."""
    projects = registry.get("projects", [])
    dev = {p["name"]: _folder(p) for p in projects if p.get("dev_folder")}
    idx = []
    for p in projects:
        if p["name"] in dev:
            idx.append(("DEV", dev[p["name"]] + "/", p["name"]))
        if p.get("drive_folder"):
            idx.append(("DRIVE", p["drive_folder"].replace("\\", "/").rstrip("/") + "/", p["name"]))
    claimed = {_folder(p) for key in ("projects", "inbox", "ideas") for p in registry.get(key) or []
               if isinstance(p, dict) and p.get("dev_folder")}
    tails: dict[str, list[str]] = {}
    for name, folder in dev.items():
        area, _, repo = folder.partition("/")
        if area in AREAS and repo and "/" not in repo:
            tails.setdefault(repo, []).append(name)
    for repo, names in tails.items():
        if len(names) == 1 and repo not in claimed and not (dev_root and (dev_root / repo).exists()):
            idx.append(("DEV", repo + "/", names[0]))
    return sorted(idx, key=lambda t: -len(t[1]))

