61	<div class="wrap">
62	  <header>
63	    <h1>Decision Desk</h1>
64	    <p class="sub">Each session adds the calls it needs from you. Click one option per card. Add a note if you want. Claude reads your answers at the next step and applies them.</p>
65	    <div class="tally" id="tally">Loading decisions…</div>
66	  </header>
67	  <div class="tabs" role="group" aria-label="Show">
68	    <button id="f-open" data-f="open" aria-pressed="true">Waiting on you</button>
69	    <button id="f-ans" data-f="ans" aria-pressed="false">Answered</button>
70	    <button id="f-done" data-f="done" aria-pressed="false">Applied</button>
71	    <button id="f-all" data-f="all" aria-pressed="false">All</button>
72	  </div>
73	  <main id="list"><div class="note">Loading decisions…</div></main>
74	</div>
75	
76	<script>
77	const S={decisions:[],answers:{},filter:"open",canWrite:true,loaded:false,err:null,drafts:{},saved:{}};
78	let db=null;
79	const $=s=>document.querySelector(s);
80	const esc=t=>String(t??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
81	
82	function stateOf(d){
83	  if(d.status==="closed")return"done";
84	  const a=S.answers[d.id];
85	  return a&&a.choice?"ans":"open";
86	}
87	
88	function render(){
89	  const ds=[...S.decisions].sort((a,b)=>(b.batch||"").localeCompare(a.batch||"")||(a.order??0)-(b.order??0));
90	  const n={open:0,ans:0,done:0};ds.forEach(d=>n[stateOf(d)]++);
91	  $("#tally").textContent=S.err?S.err:(S.loaded||ds.length)?`${n.open} waiting · ${n.ans} answered · ${n.done} applied`:"Loading decisions…";
92	  document.querySelectorAll(".tabs button").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.f===S.filter)));
93	  const shown=ds.filter(d=>S.filter==="all"||stateOf(d)===S.filter);
94	  // keep focus and caret in a note field across re-renders
95	  const ae=document.activeElement,fid=ae&&ae.tagName==="TEXTAREA"?ae.id:null,sel=fid?[ae.selectionStart,ae.selectionEnd]:null;
96	  if(!shown.length){
97	    const msg=!S.loaded&&!ds.length?(S.err||"Loading decisions…")
98	      :S.filter==="open"?"Nothing is waiting on you. New decisions appear here when a session needs a call."
99	      :"No decisions in this view yet.";
100	    $("#list").innerHTML=`<div class="note">${esc(msg)}</div>`;return;
101	  }
102	  const groups={};shown.forEach(d=>(groups[d.batch||"Undated"]??=[]).push(d));
103	  $("#list").innerHTML=Object.entries(groups).map(([b,items])=>`<section class="batch"><h2>Raised ${esc(b)}</h2>${items.map(card).join("")}</section>`).join("");
104	  if(fid){const t=document.getElementById(fid);if(t){t.focus();try{t.setSelectionRange(...sel)}catch{}}}
105	}
106	
107	function card(d){
108	  const a=S.answers[d.id]||{},st=stateOf(d),dis=!S.canWrite||st==="done"?"disabled":"";
109	  const chip=st==="done"?`<span class="chip done">Applied</span>`:st==="ans"?`<span class="chip ans">Answered</span>`:`<span class="chip open">Waiting on you</span>`;
110	  const opts=(d.options||[]).map(o=>`<button class="opt" id="o-${esc(d.id)}-${esc(o.key)}" data-id="${esc(d.id)}" data-k="${esc(o.key)}" aria-pressed="${a.choice===o.key}" ${dis}>
111	      ${o.key===d.rec?`<span class="pick">Claude's pick</span>`:""}<b>${esc(o.label)}</b>${o.detail?`<small>${esc(o.detail)}</small>`:""}</button>`).join("");
112	  const note=S.drafts[d.id]??a.note??"";
113	  return `<article class="card ${st==="ans"?"answered":""}">
114	    <div class="meta"><span class="repo">${esc(d.repo)}</span>${chip}</div>
115	    <p class="q">${esc(d.question)}</p>
116	    ${d.context?`<p class="ctx">${esc(d.context)}</p>`:""}
117	    <div class="opts">${opts}</div>
118	    ${d.result?`<p class="ctx"><b>Applied:</b> ${esc(d.result)}</p>`:""}
119	    <textarea id="n-${esc(d.id)}" data-id="${esc(d.id)}" placeholder="Note (optional)" aria-label="Note for this decision" ${dis}>${esc(note)}</textarea>
120	    <div class="row">${S.saved[d.id]?`<span class="saved">${esc(S.saved[d.id])}</span>`:""}
121	      ${a.choice&&!dis?`<button class="link" data-clear="${esc(d.id)}">Clear my answer</button>`:""}</div>
122	  </article>`;
123	}
124	
125	async function write(id,body,label){
126	  if(!db)return;
127	  try{await db.doc("answers/"+id).set(body);S.saved[id]=label}
128	  catch(e){S.saved[id]=e&&e.code==="invalid_argument"?"You can view this page but not answer here.":"Not saved. Try again.";if(e&&e.code==="invalid_argument")S.canWrite=false}
129	  render();
130	}
131	
132	document.addEventListener("click",e=>{
133	  const f=e.target.closest(".tabs button");if(f){S.filter=f.dataset.f;render();return}
134	  const o=e.target.closest(".opt");
135	  if(o&&!o.disabled){const id=o.dataset.id,prev=S.answers[id]||{};
136	    write(id,{choice:o.dataset.k,note:S.drafts[id]??prev.note??"",at:new Date().toISOString()},"Saved");return}
137	  const c=e.target.closest("[data-clear]");
138	  if(c&&db){const id=c.dataset.clear;db.doc("answers/"+id).delete().then(()=>{S.saved[id]="Cleared";delete S.drafts[id];render()}).catch(()=>{S.saved[id]="Not cleared. Try again.";render()})}
139	});
140	document.addEventListener("input",e=>{if(e.target.tagName==="TEXTAREA")S.drafts[e.target.dataset.id]=e.target.value});
141	document.addEventListener("focusout",e=>{
142	  const t=e.target;if(t.tagName!=="TEXTAREA")return;const id=t.dataset.id,prev=S.answers[id]||{};
143	  if(S.drafts[id]===undefined||S.drafts[id]===(prev.note??""))return;
144	  write(id,{choice:prev.choice??null,note:S.drafts[id],at:new Date().toISOString()},"Note saved");
145	});
146	
147	(async()=>{
148	  db=await claude.use("db");
149	  if(!db){S.err="Decisions cannot load in this view. Open the page on claude.ai while signed in.";render();return}
150	  try{const u=await claude.use("user");if(u){const c=await u.can("data.write");if(c===false)S.canWrite=false}}catch{}
151	  const timer=setTimeout(()=>{if(!S.loaded){S.err="Decisions cannot be reached yet. They may be out of date.";render()}},10000);
152	  db.collection("decisions").onSnapshot(s=>{
153	    S.decisions=s.docs.map(d=>({id:d.id,...d.data()}));
154	    if(!s.metadata.fromCache){S.loaded=true;S.err=null;clearTimeout(timer)}
155	    render();
156	  },e=>{clearTimeout(timer);S.err="Decisions stopped loading. Reload the page.";render()});
157	  db.collection("answers").onSnapshot(s=>{
158	    S.answers=Object.fromEntries(s.docs.map(d=>[d.id,d.data()]));render();
159	  },()=>{});
160	})();
161	</script>
