<div class="wrap">
  <header>
    <h1>Decision Desk</h1>
    <p class="sub">Each session adds the calls it needs from you. Click one option per card. Add a note if you want. Claude reads your answers at the next step and applies them.</p>
    <div class="tally" id="tally">Loading decisions…</div>
  </header>
  <div class="tabs" role="group" aria-label="Show">
    <button id="f-open" data-f="open" aria-pressed="true">Waiting on you</button>
    <button id="f-ans" data-f="ans" aria-pressed="false">Answered</button>
    <button id="f-done" data-f="done" aria-pressed="false">Applied</button>
    <button id="f-all" data-f="all" aria-pressed="false">All</button>
  </div>
  <main id="list"><div class="note">Loading decisions…</div></main>
</div>

<script>
const S={decisions:[],answers:{},filter:"open",canWrite:true,loaded:false,err:null,drafts:{},saved:{}};
let db=null;
const $=s=>document.querySelector(s);
const esc=t=>String(t??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

function stateOf(d){
  if(d.status==="closed")return"done";
  const a=S.answers[d.id];
  return a&&a.choice?"ans":"open";
}

function render(){
  const ds=[...S.decisions].sort((a,b)=>(b.batch||"").localeCompare(a.batch||"")||(a.order??0)-(b.order??0));
  const n={open:0,ans:0,done:0};ds.forEach(d=>n[stateOf(d)]++);
  $("#tally").textContent=S.err?S.err:(S.loaded||ds.length)?`${n.open} waiting · ${n.ans} answered · ${n.done} applied`:"Loading decisions…";
  document.querySelectorAll(".tabs button").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.f===S.filter)));
  const shown=ds.filter(d=>S.filter==="all"||stateOf(d)===S.filter);
  // keep focus and caret in a note field across re-renders
  const ae=document.activeElement,fid=ae&&ae.tagName==="TEXTAREA"?ae.id:null,sel=fid?[ae.selectionStart,ae.selectionEnd]:null;
  if(!shown.length){
    const msg=!S.loaded&&!ds.length?(S.err||"Loading decisions…")
      :S.filter==="open"?"Nothing is waiting on you. New decisions appear here when a session needs a call."
      :"No decisions in this view yet.";
    $("#list").innerHTML=`<div class="note">${esc(msg)}</div>`;return;
  }
  const groups={};shown.forEach(d=>(groups[d.batch||"Undated"]??=[]).push(d));
  $("#list").innerHTML=Object.entries(groups).map(([b,items])=>`<section class="batch"><h2>Raised ${esc(b)}</h2>${items.map(card).join("")}</section>`).join("");
  if(fid){const t=document.getElementById(fid);if(t){t.focus();try{t.setSelectionRange(...sel)}catch{}}}
}

function card(d){
  const a=S.answers[d.id]||{},st=stateOf(d),dis=!S.canWrite||st==="done"?"disabled":"";
  const chip=st==="done"?`<span class="chip done">Applied</span>`:st==="ans"?`<span class="chip ans">Answered</span>`:`<span class="chip open">Waiting on you</span>`;
  const opts=(d.options||[]).map(o=>`<button class="opt" id="o-${esc(d.id)}-${esc(o.key)}" data-id="${esc(d.id)}" data-k="${esc(o.key)}" aria-pressed="${a.choice===o.key}" ${dis}>
      ${o.key===d.rec?`<span class="pick">Claude's pick</span>`:""}<b>${esc(o.label)}</b>${o.detail?`<small>${esc(o.detail)}</small>`:""}</button>`).join("");
  const note=S.drafts[d.id]??a.note??"";
  return `<article class="card ${st==="ans"?"answered":""}">
    <div class="meta"><span class="repo">${esc(d.repo)}</span>${chip}</div>
    <p class="q">${esc(d.question)}</p>
    ${d.context?`<p class="ctx">${esc(d.context)}</p>`:""}
    <div class="opts">${opts}</div>
    ${d.result?`<p class="ctx"><b>Applied:</b> ${esc(d.result)}</p>`:""}
    <textarea id="n-${esc(d.id)}" data-id="${esc(d.id)}" placeholder="Note (optional)" aria-label="Note for this decision" ${dis}>${esc(note)}</textarea>
    <div class="row">${S.saved[d.id]?`<span class="saved">${esc(S.saved[d.id])}</span>`:""}
      ${a.choice&&!dis?`<button class="link" data-clear="${esc(d.id)}">Clear my answer</button>`:""}</div>
  </article>`;
}

async function write(id,body,label){
  if(!db)return;
  try{await db.doc("answers/"+id).set(body);S.saved[id]=label}
  catch(e){S.saved[id]=e&&e.code==="invalid_argument"?"You can view this page but not answer here.":"Not saved. Try again.";if(e&&e.code==="invalid_argument")S.canWrite=false}
  render();
}

document.addEventListener("click",e=>{
  const f=e.target.closest(".tabs button");if(f){S.filter=f.dataset.f;render();return}
  const o=e.target.closest(".opt");
  if(o&&!o.disabled){const id=o.dataset.id,prev=S.answers[id]||{};
    write(id,{choice:o.dataset.k,note:S.drafts[id]??prev.note??"",at:new Date().toISOString()},"Saved");return}
  const c=e.target.closest("[data-clear]");
  if(c&&db){const id=c.dataset.clear;db.doc("answers/"+id).delete().then(()=>{S.saved[id]="Cleared";delete S.drafts[id];render()}).catch(()=>{S.saved[id]="Not cleared. Try again.";render()})}
});
document.addEventListener("input",e=>{if(e.target.tagName==="TEXTAREA")S.drafts[e.target.dataset.id]=e.target.value});
document.addEventListener("focusout",e=>{
  const t=e.target;if(t.tagName!=="TEXTAREA")return;const id=t.dataset.id,prev=S.answers[id]||{};
  if(S.drafts[id]===undefined||S.drafts[id]===(prev.note??""))return;
  write(id,{choice:prev.choice??null,note:S.drafts[id],at:new Date().toISOString()},"Note saved");
});

(async()=>{
  db=await claude.use("db");
  if(!db){S.err="Decisions cannot load in this view. Open the page on claude.ai while signed in.";render();return}
  try{const u=await claude.use("user");if(u){const c=await u.can("data.write");if(c===false)S.canWrite=false}}catch{}
  const timer=setTimeout(()=>{if(!S.loaded){S.err="Decisions cannot be reached yet. They may be out of date.";render()}},10000);
  db.collection("decisions").onSnapshot(s=>{
    S.decisions=s.docs.map(d=>({id:d.id,...d.data()}));
    if(!s.metadata.fromCache){S.loaded=true;S.err=null;clearTimeout(timer)}
    render();
  },e=>{clearTimeout(timer);S.err="Decisions stopped loading. Reload the page.";render()});
  db.collection("answers").onSnapshot(s=>{
    S.answers=Object.fromEntries(s.docs.map(d=>[d.id,d.data()]));render();
  },()=>{});
})();
</script>

