// "I'm done": post one comment and send it to a Claude session watching this page; always also leave signals/done
// in the database so a later session sees it. The send runs first, inside the click, because it needs the gesture.
let comments=null;
const doneMsg=t=>{$("#done-msg").textContent=t};
function doneText(){
  const ready=S.decisions.filter(d=>stateOf(d)==="ans");
  const parts=ready.map(d=>{const a=S.answers[d.id]||{},n=(a.note||"").replace(/\s+/g," ").trim();return `${d.id} = ${a.choice}${n?` (note: ${n})`:""}`});
  const t=ready.length?`I'm done on the Decision Desk. ${ready.length} answered, ready to apply: ${parts.join("; ")}`
    :"I'm done on the Decision Desk. Nothing new is answered.";
  return {ids:ready.map(d=>d.id),text:t.length>3500?t.slice(0,3490)+" …":t};   // comment limit is 4 KiB
}
$("#done-btn").addEventListener("click",async()=>{
  const btn=$("#done-btn"),{ids,text}=doneText();btn.disabled=true;doneMsg("Sending…");
