    if(can==="available"){await comments.sendToClaude({anchor:await comments.anchorFor(btn),text});sent=true}
    else why=can==="no_session"?"No Claude session is watching this page right now.":"";
  }catch(e){why=e&&e.code==="rate_limited"?"Sent too often. Wait a minute and press again.":""}
  let noted=false;
  try{if(db){await db.doc("signals/done").set({at:new Date().toISOString(),ids,sent});noted=true}}catch{}
