$("#done-btn").addEventListener("click",async()=>{
  const btn=$("#done-btn");if(btn.disabled)return;
  const stop=blocked();if(stop){doneMsg(stop);return}
  const ids=S.decisions.filter(d=>stateOf(d)==="ans").map(d=>d.id),n=ids.length;
  const text=`I'm done on the Decision Desk (${n} answered, not yet applied). Read the answers collection and apply them.`;
  S.cooldown=true;doneReady();doneMsg("Sending...");
  let sent=false,why="";
  try{
    const can=comments?await comments.canSendToClaude():"off";
    const anchor=can==="available"?await comments.anchorFor(btn):null;
    const late=blocked();if(late){doneMsg(late);S.cooldown=false;doneReady();return}
    if(anchor){await comments.sendToClaude({anchor,text});sent=true}
    else if(can==="no_session")why="No Claude session is watching this page right now.";
  }catch(e){why=e&&e.code==="rate_limited"?"Sent too often. Wait a minute and press again.":""}
  let noted=false;try{await db.doc("signals/done").set({at:new Date().toISOString(),answered:n,ids,sent});noted=true}catch{}
  doneMsg(sent?"Sent to Claude. A session will read your answers now."
    :`${why?why+" ":""}${noted?"A note was saved. ":"The note did not save. "}Tell Claude in chat that you are done.`);
  setTimeout(()=>{S.cooldown=false;doneReady()},sent?60000:5000);
});
